package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_siblingIndex_TriageGen1Test {

    private Node node;
    private Node parentNode;
    private Node firstChild;
    private Node secondChild;

    @Before
    public void setUp() {
        parentNode = new Node(Tag.valueOf("div"));
        firstChild = new Node(Tag.valueOf("p"));
        secondChild = new Node(Tag.valueOf("span"));

        parentNode.addChildren(firstChild);
        parentNode.addChildren(secondChild);

        node = firstChild;
        node.setParentNode(parentNode);
        secondChild.setParentNode(parentNode);
    }

    @Test
    public void testSiblingIndex_WhenFirstChild() {
        assertEquals(0, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_WhenSecondChild() {
        node = secondChild;
        assertEquals(1, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_NoSiblings() {
        Node singleChildNode = new Node(Tag.valueOf("a"));
        singleChildNode.setParentNode(parentNode);
        assertEquals(0, singleChildNode.siblingIndex());
    }

    @Test
    public void testSiblingIndex_AfterRemoval() {
        parentNode.removeChildren(); // Remove all children
        node = new Node(Tag.valueOf("b"));
        node.setParentNode(parentNode);
        assertEquals(0, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_WithMultipleSiblings() {
        Node thirdChild = new Node(Tag.valueOf("div"));
        parentNode.addChildren(thirdChild);
        thirdChild.setParentNode(parentNode);

        assertEquals(2, thirdChild.siblingIndex());
    }
}
